import {ProviderLogo} from '@github-ui/models-byok/providers/ProviderLogo'
import type {CustomKey, CustomModel} from '@github-ui/models-byok/types'
import {AiModelIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Stack} from '@primer/react'
import {clsx} from 'clsx'
import {useId} from 'react'

import styles from './AvailableModel.module.css'

interface AvailableModelProps {
  customKey: CustomKey
  model: CustomModel
}

export function AvailableModel({customKey, model}: AvailableModelProps) {
  const id = useId()
  const labelId = `${id}-label`

  return (
    <div className={clsx(styles.AvailableModel, 'Box-row--hover-gray')}>
      <Stack.Item grow>
        <div id={labelId} className={styles.AvailableModelName}>
          <ProviderLogo provider={customKey.provider} className={styles.AvailableModelLogo} />
          <span data-area="model_name">{model.name ?? model.slug}</span>
          <span data-area="key_name">{customKey.name}</span>
        </div>
      </Stack.Item>

      <ActionMenu>
        <ActionMenu.Button aria-describedby={labelId}>Enabled</ActionMenu.Button>
        <ActionMenu.Overlay width="medium">
          <ActionList selectionVariant="multiple">
            <ActionList.GroupHeading>This model is enabled for:</ActionList.GroupHeading>
            <GitHubModelsItem selected={model.enabled.models} />
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </div>
  )
}

export function GitHubModelsItem({selected}: {selected: boolean}) {
  return (
    <ActionList.Item
      selected={selected}
      inactiveText="Change this setting by going to Models &gt; Development &gt; Permissions"
    >
      <ActionList.LeadingVisual>
        <AiModelIcon size="small" />
      </ActionList.LeadingVisual>
      GitHub Models
    </ActionList.Item>
  )
}

try{ AvailableModel.displayName ||= 'AvailableModel' } catch {}
try{ GitHubModelsItem.displayName ||= 'GitHubModelsItem' } catch {}