import {FormControl, Stack, TextInput} from '@primer/react'
import {useId, useState} from 'react'
import * as z from 'zod'

import {modelIDSchema} from '../../../helpers/model-id-schema'
import {getFormValidationNode} from '../../../helpers/Validation'
import styles from '../../AddEditDialog.module.css'
import {ProviderModelSelectorPane} from '../ProviderModelSelectorPane'
import type {ProviderFieldProps} from '../types'

type AzureHostname = `${string}${(typeof validHostnames)[number]}${string}`

const azureOpenAIHostname = 'openai.azure.com'
// Keep in sync with `VALID_AZURE_HOSTNAMES` in packages/models_byok/app/models/models_byok/custom_key.rb
const validHostnames = [
  'models.ai.azure.com',
  'inference.ml.azure.com',
  azureOpenAIHostname,
  'services.ai.azure.com',
  'cognitiveservices.azure.com',
] as const

function stringIsValidHostname(value: string, hostnames: readonly string[] = validHostnames): value is AzureHostname {
  try {
    // We want to try and create a url out of the value to validate it
    // eslint-disable-next-line no-restricted-syntax
    const url = new URL(value)
    const hostname = url.hostname.toLowerCase()
    return hostnames.some(h => hostname === h || hostname.endsWith(`.${h}`))
  } catch {
    return false
  }
}

const hostnameValidator = z.lazy(() =>
  z.custom<AzureHostname>(value => {
    if (typeof value !== 'string') return false
    return stringIsValidHostname(value)
  }, 'Deployment URL must be a valid Microsoft Foundry endpoint'),
)

export const azureFormSchema = {
  provider: z.literal('azureai'),
  deployment_url: z.string().pipe(hostnameValidator),
  models: z.array(
    z
      .object({
        id: z.number().optional(),
        slug: modelIDSchema.optional(),
        name: z.string().nullish(),
      })
      .refine(data => data.id || data.slug, {
        message: 'Either "id" or "slug" must be provided',
        path: ['id', 'slug'],
      }),
    'Please select a model',
  ),
} as const

export function AzureAIFields({
  apiKey,
  customKey,
  validation,
  isPending,
  setValidation,
  onSetAdditionalData,
}: ProviderFieldProps<'azureai'>) {
  const id = useId()
  const [deploymentUrl, setDeploymentUrl] = useState((customKey && customKey?.deploymentUrl) || '')
  const deploymentUrlValidationId = `deployment_url-validation-${id}`
  const modelsValidationId = `models-validation-${id}`
  const isAzureOpenAI = stringIsValidHostname(deploymentUrl, [azureOpenAIHostname])

  return (
    <>
      <FormControl required disabled={isPending}>
        <FormControl.Label>Deployment URL</FormControl.Label>
        <TextInput
          name="deployment_url"
          data-1p-ignore
          className="width-full"
          autoComplete="off"
          aria-describedby={deploymentUrlValidationId}
          defaultValue={deploymentUrl}
          onBlur={e => setDeploymentUrl(e.currentTarget.value)}
        />
        {getFormValidationNode(validation?.deployment_url, deploymentUrlValidationId)}
      </FormControl>

      <Stack.Item grow className={styles.ModelSelectorLayout}>
        <FormControl disabled={isPending}>
          <FormControl.Label>Available models</FormControl.Label>
          <ProviderModelSelectorPane
            provider="azureai"
            apiKey={apiKey}
            customKeyId={customKey?.id}
            deploymentUrl={deploymentUrl}
            isPending={isPending}
            setValidation={setValidation}
            onSetAdditionalData={onSetAdditionalData}
            aria-describedby={modelsValidationId}
            canAddModels={!isAzureOpenAI}
          />
          {getFormValidationNode(validation?.models, modelsValidationId)}
        </FormControl>
      </Stack.Item>
    </>
  )
}

try{ AzureAIFields.displayName ||= 'AzureAIFields' } catch {}